registry.content:
.df-alert {
  font-family: var(--df-font);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 0.7rem 0.9rem;
  border: 2px solid var(--df-ink);
  border-left-width: 6px;
  border-radius: var(--df-radius);
  background: var(--df-paper);
  box-shadow: var(--df-shadow-sm);
}
.df-alert--info { border-left-color: var(--df-primary); }
.df-alert--warn { border-left-color: var(--df-warn); }
.df-alert--bad  { border-left-color: var(--df-tertiary); }
.df-alert--ok   { border-left-color: var(--df-secondary); }

import * as React from "react";
import "./tokens.css";

export interface AlertProps extends React.HTMLAttributes<HTMLDivElement> {
  tone?: "info" | "warn" | "bad" | "ok";
}

/* alerta com borda dura — feedback de operação (preço, ban, erro) */
export function Alert({ tone = "info", className = "", children, ...props }: AlertProps) {
  return (
    <div role="alert" className={`df-alert df-alert--${tone} ${className}`.trim()} {...props}>
      {children}
    </div>
  );
}

.df-badge {
  display: inline-grid;
  place-items: center;
  min-width: 1.4rem;
  height: 1.4rem;
  padding: 0 0.35rem;
  font-family: var(--df-font);
  font-size: 0.72rem;
  font-weight: 800;
  border: 2px solid var(--df-ink);
  border-radius: 999px;
  background: var(--df-primary);
  color: var(--df-ink);
  box-shadow: var(--df-shadow-sm);
}
.df-badge--brand { background: var(--df-brand); color: #fff; }
.df-badge--warn  { background: var(--df-warn); }
.df-badge--bad   { background: var(--df-tertiary); color: #fff; }

import * as React from "react";
import "./tokens.css";

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: "primary" | "brand" | "warn" | "bad";
}

/* badge numerico (contador de tarefas, notificacoes) */
export function Badge({ tone = "primary", className = "", children, ...props }: BadgeProps) {
  return (
    <span className={`df-badge df-badge--${tone} ${className}`.trim()} {...props}>
      {children}
    </span>
  );
}

/* classes do df-btn — tokens em tokens.css */
.df-btn {
  --btn-bg: var(--df-paper);
  --btn-fg: var(--df-ink);
  font-family: var(--df-font);
  font-weight: 700;
  border: 2px solid var(--df-ink);
  border-radius: var(--df-radius);
  background: var(--btn-bg);
  color: var(--btn-fg);
  box-shadow: var(--df-shadow);
  cursor: pointer;
  transition: transform 80ms ease, box-shadow 80ms ease;
  line-height: 1;
}
.df-btn:hover { transform: translate(-1px, -1px); box-shadow: 0 5px 0 var(--df-ink); }
.df-btn:active { transform: translate(2px, 2px); box-shadow: none; }
.df-btn:focus-visible { outline: 3px solid var(--df-primary); outline-offset: 2px; }
.df-btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none; box-shadow: var(--df-shadow-sm); }

.df-btn--paper   { --btn-bg: var(--df-paper); }
.df-btn--primary { --btn-bg: var(--df-primary); }
.df-btn--brand   { --btn-bg: var(--df-brand); --btn-fg: #fff; }
.df-btn--danger  { --btn-bg: var(--df-tertiary); --btn-fg: #fff; }
.df-btn--ghost   { --btn-bg: transparent; box-shadow: none; }

.df-btn--sm { padding: 0.35rem 0.7rem; font-size: 0.8rem; }
.df-btn--md { padding: 0.55rem 1rem; font-size: 0.9rem; }
.df-btn--lg { padding: 0.8rem 1.4rem; font-size: 1.05rem; }

import * as React from "react";
import "./tokens.css";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "paper" | "primary" | "brand" | "danger" | "ghost";
  size?: "sm" | "md" | "lg";
}

/* neobrutal: borda 2px ink, sombra dura que "desloca" no hover/active */
export function Button({ variant = "paper", size = "md", className = "", ...props }: ButtonProps) {
  const base = [
    "df-btn",
    `df-btn--${variant}`,
    `df-btn--${size}`,
    className,
  ].join(" ");
  return <button className={base} {...props} />;
}

.df-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-family: var(--df-font);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  padding: 0.25rem 0.6rem;
  border: 2px solid var(--df-ink);
  border-radius: 999px;
  background: var(--df-paper);
  color: var(--df-ink);
  box-shadow: var(--df-shadow-sm);
}
.df-chip__dot { width: 8px; height: 8px; border-radius: 50%; background: var(--df-ink); }
.df-chip--ok   { background: var(--df-secondary); }
.df-chip--ok .df-chip__dot   { background: #0e9f6e; }
.df-chip--warn { background: var(--df-warn); }
.df-chip--warn .df-chip__dot { background: #b45309; }
.df-chip--bad  { background: var(--df-tertiary); color: var(--df-ink); }
.df-chip--bad .df-chip__dot  { background: #c2410c; }
.df-chip--info { background: var(--df-lilac); }
.df-chip--info .df-chip__dot { background: var(--df-primary); }

import * as React from "react";
import "./tokens.css";

export interface ChipProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: "ok" | "warn" | "bad" | "info";
  dot?: boolean;
}

/* chip de estado (preço ok, alerta, radar...) com dot de status */
export function Chip({ tone = "info", dot = false, className = "", children, ...props }: ChipProps) {
  return (
    <span className={`df-chip df-chip--${tone} ${className}`} {...props}>
      {dot && <span className="df-chip__dot" aria-hidden />}
      {children}
    </span>
  );
}

.df-input {
  font-family: var(--df-font);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--df-ink);
  background: var(--df-paper);
  border: 2px solid var(--df-ink);
  border-radius: var(--df-radius);
  box-shadow: var(--df-shadow-sm);
  padding: 0.55rem 0.8rem;
  min-width: 0;
  width: 100%;
}
.df-input::placeholder { color: var(--df-dim); font-weight: 500; }
.df-input:focus-visible { outline: 3px solid var(--df-primary); outline-offset: 1px; }
.df-input--invalid { border-color: var(--df-tertiary); background: #fef2f2; }
.df-input:disabled { opacity: 0.5; cursor: not-allowed; }

import * as React from "react";
import "./tokens.css";

export interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  invalid?: boolean;
}

export function Input({ invalid = false, className = "", ...props }: InputProps) {
  return (
    <input
      aria-invalid={invalid || undefined}
      className={`df-input ${invalid ? "df-input--invalid" : ""} ${className}`.trim()}
      {...props}
    />
  );
}

/* activity-dot — ponto de estado que pulsa enquanto o bot trabalha.
   Neobrutal: quadradinho ink que "desloca" 2px no passo (não pulsa suave).
   Uso: <span class="df-activity-dot df-activity-dot--b1" /> */
.df-activity-dot {
  --ad-c: var(--df-ink);
  --ad-size: 10px;
  display: inline-block;
  width: var(--ad-size);
  height: var(--ad-size);
  border: 2px solid var(--df-ink);
  border-radius: 3px;                 /* quase quadrado — linguagem neobrutal */
  background: var(--ad-c);
  box-shadow: var(--df-shadow);
  flex: none;
}
/* atividade: desloca 2px no loop, em passos (nada de lerp suave) */
.df-activity-dot--live {
  animation: df-dot-step var(--df-motion-pulse) infinite var(--df-motion-ease-step);
}
@keyframes df-dot-step {
  0%, 100% { transform: translate(0, 0); }
  50%      { transform: translate(2px, 2px); }
}
/* cores por bot — D3: b1 pink · b2 mint · b6 lilac · b7 canary · bt canary · operador coral */
.df-activity-dot--b1   { --ad-c: var(--df-primary); }
.df-activity-dot--b2   { --ad-c: var(--df-secondary); --ad-c-sh: rgba(0,0,0,.35); }
.df-activity-dot--b6   { --ad-c: var(--df-lilac); }
.df-activity-dot--b7   { --ad-c: var(--df-warn); }
.df-activity-dot--bt   { --ad-c: var(--df-warn); }
.df-activity-dot--op   { --ad-c: var(--df-tertiary); }
.df-activity-dot--idle { background: var(--df-paper); }  /* ocioso: vazio */

import * as React from "react";
import "./tokens.css";
import "./activity-dot.css";

export type BotId = "b1" | "b2" | "b6" | "b7" | "bt" | "op";

export interface ActivityDotProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** qual bot está trabalhando (cor canônica D3) */
  bot?: BotId;
  /** true = animado (trabalhando); false/omit = parado */
  live?: boolean;
}

/* ponto de atividade do bot — quadrado ink que desloca 2px em steps enquanto
   trabalha; parado fica branco com borda (vazio). */
export function ActivityDot({ bot, live = false, className = "", ...props }: ActivityDotProps) {
  const cls = [
    "df-activity-dot",
    bot ? `df-activity-dot--${bot}` : "",
    live ? "df-activity-dot--live" : "df-activity-dot--idle",
    className,
  ].filter(Boolean).join(" ");
  return <span aria-label={live ? "trabalhando" : "ocioso"} className={cls} {...props} />;
}

/* activity-strip — faixa de 1 linha: identidade do bot + verbo vivo + steps.
   Envolve o ticker nativo do Hermes (tool-ticker) com a identidade DROPFOOD.
   Border-left 6px na cor do bot (D3); fundo paper; sombra neobrutal. */
.df-activity-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--df-font);
  font-size: 0.78rem;
  font-weight: 600;
  padding: 6px 10px;
  border: 2px solid var(--df-ink);
  border-left-width: 6px;
  border-radius: var(--df-radius);
  background: var(--df-paper);
  box-shadow: var(--df-shadow-sm);
  min-width: 0;
}
.df-activity-strip--b1 { border-left-color: var(--df-primary); }
.df-activity-strip--b2 { border-left-color: var(--df-secondary); }
.df-activity-strip--b6 { border-left-color: var(--df-lilac); }
.df-activity-strip--b7 { border-left-color: var(--df-warn); }
.df-activity-strip--bt { border-left-color: var(--df-warn); }
.df-activity-strip--op { border-left-color: var(--df-tertiary); }

.df-activity-strip__who {
  font-family: var(--df-font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--df-dim);
  white-space: nowrap;
}
.df-activity-strip__verb {
  font-weight: 700;
  white-space: nowrap;
}
.df-activity-strip__inner {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  font-size: 0.75rem;
}

import * as React from "react";
import "./tokens.css";
import "./activity-dot.css";
import "./activity-strip.css";
import { ActivityDot, type BotId } from "./activity-dot";

export interface ActivityStripProps extends React.HTMLAttributes<HTMLDivElement> {
  /** bot trabalhando — dita cor e rótulo (D3) */
  bot: BotId;
  /** verbo vivo: "escaneando concorrentes…" */
  verb?: string;
  /** conteúdo rolável — o ticker nativo do Hermes passa aqui */
  children?: React.ReactNode;
}

const WHO: Record<BotId, string> = {
  b1: "b1 estrategista",
  b2: "b2 radar",
  b6: "b6 revisor",
  b7: "b7 controle",
  bt: "bt treinador",
  op: "operador",
};

/* faixa 1-linha de atividade por bot: dot animado + quem + verbo + conteúdo
   (ticker). Onde o run-ticker do Hermes é wrapper para dar identidade. */
export function ActivityStrip({ bot, verb, children, className = "", ...props }: ActivityStripProps) {
  return (
    <div className={`df-activity-strip df-activity-strip--${bot} ${className}`.trim()} {...props}>
      <ActivityDot bot={bot} live />
      <span className="df-activity-strip__who">{WHO[bot]}</span>
      {verb && <span className="df-activity-strip__verb">{verb}</span>}
      <span className="df-activity-strip__inner">{children}</span>
    </div>
  );
}

/* step-progress — quadrinhos neobrutais de progresso (passos do bot).
   Sem barra de progresso: quadrados ink preenchidos por passo concluído.
   Uso: .df-steps[data-total="5"][data-done="3"] */
.df-steps {
  display: inline-flex;
  gap: 3px;
  align-items: center;
}
.df-steps__sq {
  width: 8px;
  height: 8px;
  border: 2px solid var(--df-ink);
  border-radius: 2px;
  background: var(--df-paper);
  transition: background var(--df-motion-fast) var(--df-motion-ease);
}
.df-steps__sq--done {
  background: var(--df-ink);
}
.df-steps__sq--live {
  background: var(--df-primary);
  animation: df-steps-blink var(--df-motion-pulse) infinite var(--df-motion-ease-step);
}
@keyframes df-steps-blink {
  0%, 100% { transform: translate(0, 0); }
  50%      { transform: translate(1px, 1px); }
}
.df-steps__label {
  font-family: var(--df-font-mono);
  font-size: 0.62rem;
  font-weight: 700;
  color: var(--df-dim);
  margin-left: 5px;
}

import * as React from "react";
import "./tokens.css";
import "./step-progress.css";

export interface StepProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  total: number;
  done: number;
  /** true = o passo ATUAL pisca pink (está rodando agora) */
  live?: boolean;
  label?: string;
}

/* progresso neobrutal em passos: feito = ink, atual = pink piscando,
   futuro = vazio. Nunca uma barra — passos são discretos. */
export function StepProgress({ total, done, live = false, label, className = "", ...props }: StepProgressProps) {
  const squares = Array.from({ length: Math.max(0, total) }, (_, i) => (
    <span
      key={i}
      className={
        i < done ? "df-steps__sq df-steps__sq--done" :
        i === done && live ? "df-steps__sq df-steps__sq--live" :
        "df-steps__sq"
      }
    />
  ));
  return (
    <div className={`df-steps ${className}`.trim()} role="progressbar" aria-valuemin={0} aria-valuemax={total} aria-valuenow={done} {...props}>
      {squares}
      {label && <span className="df-steps__label">{label}</span>}
    </div>
  );
}

/* working-card — card expandido de trabalho do bot (missão, steps, resultado).
   Reaproveita a identidade do activity-strip por cima; base = run-summary +
   delegate-card do Hermes. Bloco autônomo com sombra forte. */
.df-working-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: 2px solid var(--df-ink);
  border-radius: var(--df-radius);
  background: var(--df-paper);
  box-shadow: var(--df-shadow);
  padding: 12px 14px;
  font-family: var(--df-font);
  min-width: 0;
}
.df-working-card__head {
  display: flex;
  align-items: center;
  gap: 8px;
}
.df-working-card__title {
  font-weight: 700;
  font-size: 0.85rem;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.df-working-card__meta {
  font-family: var(--df-font-mono);
  font-size: 0.62rem;
  color: var(--df-dim);
  white-space: nowrap;
}
.df-working-card__body {
  font-size: 0.78rem;
  color: var(--df-dim);
  line-height: 1.5;
}
.df-working-card__foot {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--df-font-mono);
  font-size: 0.62rem;
  color: var(--df-dim);
}

import * as React from "react";
import "./tokens.css";
import "./working-card.css";
import "./activity-dot.css";
import { ActivityDot, type BotId } from "./activity-dot";
import { StepProgress } from "./step-progress";

export interface WorkingCardProps extends React.HTMLAttributes<HTMLDivElement> {
  /** bot que está trabalhando (cor e rótulo D3) */
  bot: BotId;
  title: string;
  stepsDone?: number;
  stepsTotal?: number;
  meta?: string;      // ex.: "3 de 7 concorrentes"
  duration?: string;  // ex.: "12s"
  children?: React.ReactNode;
}

/* card expandido de trabalho: quem, o quê, progresso em passos e foot com
   duração. Base do modo expandido da atividade (working-card do mapa). */
export function WorkingCard({
  bot, title, stepsDone = 0, stepsTotal = 0, meta, duration,
  children, className = "", ...props
}: WorkingCardProps) {
  return (
    <div className={`df-working-card ${className}`.trim()} {...props}>
      <div className="df-working-card__head">
        <ActivityDot bot={bot} live />
        <span className="df-working-card__title">{title}</span>
        {meta && <span className="df-working-card__meta">{meta}</span>}
      </div>
      {stepsTotal > 0 && (
        <StepProgress total={stepsTotal} done={stepsDone} live label={duration} />
      )}
      {children && <div className="df-working-card__body">{children}</div>}
      {duration && !stepsTotal && (
        <div className="df-working-card__foot">{duration}</div>
      )}
    </div>
  );
}

/* bot-avatar — avatar do bot com cor canônica + iniciais (D3).
   Square neobrutal com borda ink e a cor do bot; inicial em Archivo Black.
   Variações: b1 pink "B1", b2 mint "B2", b6 lilac "B6", b7 canary "B7",
   bt canary "BT", operador coral "OP" (ink sobre a cor sempre — contraste). */
.df-bot-avatar {
  --ba-bg: var(--df-ink);
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 2px solid var(--df-ink);
  border-radius: 6px;
  background: var(--ba-bg);
  color: var(--df-ink);
  font-family: var(--df-font-display);
  font-size: 0.62rem;
  letter-spacing: 0.02em;
  box-shadow: var(--df-shadow-sm);
  flex: none;
  user-select: none;
}
.df-bot-avatar--b1 { background: var(--df-primary); }
.df-bot-avatar--b2 { background: var(--df-secondary); }
.df-bot-avatar--b6 { background: var(--df-lilac); }
.df-bot-avatar--b7 { background: var(--df-warn); }
.df-bot-avatar--bt { background: var(--df-warn); }
.df-bot-avatar--op { background: var(--df-tertiary); }
.df-bot-avatar--sm { width: 18px; height: 18px; font-size: 0.5rem; border-radius: 5px; }
.df-bot-avatar--lg { width: 34px; height: 34px; font-size: 0.8rem; border-radius: 8px; }

import * as React from "react";
import "./tokens.css";
import "./bot-avatar.css";
import type { BotId } from "./activity-dot";

export interface BotAvatarProps extends React.HTMLAttributes<HTMLSpanElement> {
  bot: BotId;
  size?: "sm" | "md" | "lg";
}

const INITIAL: Record<BotId, string> = {
  b1: "B1", b2: "B2", b6: "B6", b7: "B7", bt: "BT", op: "OP",
};

/* avatar de bot: quadrado neobrutal com a cor canônica do bot + iniciais.
   Contraste: a cor é fundo, as iniciais são ink (AA sobre pink/mint/etc.). */
export function BotAvatar({ bot, size = "md", className = "", ...props }: BotAvatarProps) {
  return (
    <span className={`df-bot-avatar df-bot-avatar--${bot} ${size !== "md" ? `df-bot-avatar--${size}` : ""} ${className}`.trim()} {...props}>
      {INITIAL[bot]}
    </span>
  );
}
